const entrada = $input.first().json;

// Extraer datos con valores por defecto seguros
const telefono = String(entrada.telefono || '').replace(/[^0-9]/g, '');
const nombre = (entrada.nombre || '').trim() || `Prospecto WhatsApp ${telefono}`;
const servicio = (entrada.servicio || 'Seguridad Electrónica').trim();
const direccion = (entrada.direccion || 'No especificada').trim();
const estado = entrada.estado || (entrada.derivar ? 'Atención Urgente' : 'No Contactado');

// Si la IA derivó a humano o no hay respuesta, mensaje de respaldo
const mensajeRespuesta = entrada.derivar || !entrada.respuesta
  ? 'Gracias por comunicarte con Atrios. Un asesor comercial especializado se pondrá en contacto contigo a la brevedad para brindarte una atención personalizada.'
  : entrada.respuesta;

return [{
  json: {
    telefono,
    nombre,
    servicio,
    direccion,
    estado,
    mensaje_final: mensajeRespuesta,
    Last_Name: nombre,
    Company: 'Particular - Atrios [TEST]',
    Phone: telefono,
    Street: direccion,
    Lead_Status: estado,
    Description: `Servicio de interés: ${servicio} | Origen: WhatsApp Bot Atrios | Derivar a Humano: ${entrada.derivar ? 'SÍ' : 'NO'}`
  }
}];
